<?php session_name('VS_ADMIN');session_start();if(isset($_SESSION['user_id'])&&($_SESSION['user_role']??'')==='admin'){header('Location: index.php');exit;}require_once '../config/app.php';?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VS Travells Admin Login</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><section class="admin-auth"><form id="adminLogin" class="admin-auth-card"><div class="brand"><span class="brand-mark">VS</span><span>VS Travells<small>Administration</small></span></div><span class="eyebrow dark">SECURE ADMIN PORTAL</span><h1>Admin Login</h1><p class="muted">This portal is separate from the customer website.</p><div id="msg"></div><label>Admin email<input type="email" id="email" required></label><label>Password<input type="password" id="password" required></label><button class="btn wide">Enter Admin Console</button><p class="auth-switch"><a href="../login.php">← Customer portal</a></p></form></section><script>
const adminLogin=document.getElementById('adminLogin'),adminMsg=document.getElementById('msg');
adminLogin.addEventListener('submit',async e=>{e.preventDefault();const email=document.getElementById('email').value.trim(),password=document.getElementById('password').value;try{const r=await fetch('../api/auth/admin-login.php',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({email,password})});const j=await r.json();adminMsg.innerHTML=`<div class="message ${j.success?'success':'error'}">${j.message}</div>`;if(j.success)setTimeout(()=>location.href='index.php',400)}catch(_){adminMsg.innerHTML='<div class="message error">Unable to sign in to the admin portal.</div>'}});
</script></body></html>